respuesta_cruda:
{
  "seed_id": "sem-073",
  "variantes": [
    {
      "texto_dialectal": "Che, cuando vos sos el que siempre se hace el otario para no responder la pregunta, los demás te miran con desconfianza.",
      "traduccion": "Buddy, when you always play dumb to avoid answering a question, the others look at you with suspicion.",
      "registro": "informal",
      "contexto_uso": "un amigo que habla con otro amigo en un grupo de colegas sobre una actitud evasiva"
    },
    {
      "texto_dialectal": "No me hagas el otario, ¿vas a explicarme el proceso de auditoría o no?",
      "traduccion": "Don't play dumb with me, are you going to explain the audit process or not?",
      "registro": "jerga",
      "contexto_uso": "un empleado reprochando a su compañero a la hora de discutir trabajo"
    },
    {
      "texto_dialectal": "Se quedó haciendo el otario durante toda la reunión y nadie creyó su argumento.",
      "traduccion": "He kept playing dumb during the whole meeting and nobody believed his argument.",
      "registro": "formal",
      "contexto_uso": "un narrador describiendo la conducta de un interlocutor en una sesión corporativa"
    },
    {
      "texto_dialectal": "¡Vos te haces el otario, pero te lo saben, que el jefe ya vio la factura!?",
      "traduccion": "You play dumb, but everyone knows, the boss already saw the invoice!?",
      "registro": "informal",
      "contexto_uso": "un colega burlándose con tono de risa de otro que intenta evadir responsabilidad"
    },
    {
      "texto_dialectal": "En la calle, el muchacho se hizo el otario cuando la policía le pidió el pasaporte.",
      "traduccion": "On the street, the kid played dumb when the police asked for his passport.",
      "registro": "informal",
      "contexto_uso": "un narrador describiendo una situación de control policial en la ciudad"
    },
    {
      "texto_dialectal": "Si sigue haciéndose el otario, no va a salir nada con el trámite.",
      "traduccion": "If you keep playing dumb, nothing will come of the procedure.",
      "registro": "informal",
      "contexto_uso": "un abogado advierte a un cliente sobre las consecuencias de fingir ignorancia"
    }
  ]
}
